LABELS = {"REQUIRED": "חובה", "CONDITIONAL": "מותנה", "OPTIONAL": "רשות", "UNKNOWN": "לא ידוע — נדרשת מדיניות בנק"}


def main() -> None:
    keys = [k for k, _ in COLUMNS]
    for d in DOCS:
        missing = [k for k in keys if k not in d]
        if missing:
            raise SystemExit(f"{d.get('doc_type')}: missing {missing}")
    with OUT_CSV.open("w", encoding="utf-8-sig", newline="") as fh:
        w = csv.writer(fh)
        w.writerow([h for _, h in COLUMNS])
        for d in DOCS:
            w.writerow([d[k] for k in keys])
    lines = [
        "# Document B — מטריצת דרישות מסמכי משכנתא (MORTGAGE_DOCUMENT_REQUIREMENTS_MATRIX)",
        "",
        "**גרסה:** 1.0 (טיוטה למימוש) · **תאריך:** 12.10.2026 · **מקור הנתונים:** `B_MORTGAGE_DOCUMENT_REQUIREMENTS_MATRIX/build_matrix.py` (מייצר גם את קובץ ה־CSV — אין לערוך ידנית).",
        "",
        "> **אזהרת שימוש.** כל שורה כאן היא *קטלוג מחקרי*. גם `CONFIRMED_PUBLIC_BANK_REQUIREMENT` פירושו \"מופיע בדף ציבורי רשמי של מזרחי־טפחות\" — לא נוהל פנימי מאושר. "
        "רשימת הדרישות של תיק מסוים מגיעה מהבנק (דרך ה־MCS) ומפורטת באישור העקרוני (הוראה 451 §4c(c)(3); R2 C4). VisionTrace לעולם אינו מוסיף דרישה שהלקוח לא קיבל.",
        "",
        "**מקרא סיווג דרישה (עמודה 9):** חובה · מותנה · רשות · לא ידוע (UNKNOWN / BANK POLICY REQUIRED).  ",
        "**מקרא בסיס הכלל (עמודה 22):** `CONFIRMED_PUBLIC_BANK_REQUIREMENT` (דף רשמי של הבנק) · `STATUTORY` (חוק/תקנה/הוראת בנק ישראל) · `PROPOSED_VALIDATION` (כלל בדיקה מוצע) · `BANK_POLICY_REQUIRED` (חסר מקור — נדרשת החלטת בנק).  ",
        "**מקרא היקף VisionTrace:** `REVIEW` נבדק · `CONTEXT_ONLY` משמש כהקשר בלבד · `OUT` מחוץ להיקף.  ",
        "**מזהי מקורות** (MZ-xx, BOI-xx, LAW-xx, LAND-xx, SEC-xx, PEER-xx, TECH-xx) מוגדרים ב־`G_RESEARCH_SOURCES_AND_OPEN_QUESTIONS.md`.",
        "",
        "## 1. טבלת סיכום",
        "",
        "| # | קוד | מסמך | משפחה | סיווג | שלב | עדיפות | היקף | רובריקה | בסיס | ביטחון |",
        "|---|---|---|---|---|---|---|---|---|---|---|",
    ]
    for i, d in enumerate(DOCS, 1):
        lines.append(f"| {i} | `{d['doc_type']}` | {d['name_he']} | {d['family']} | {LABELS[d['requirement_class']]} | {d['stage']} | "
                     f"**{d['priority']}** | {d['vt_scope']} | {d['rubric']} | `{d['rule_basis']}` | {d['confidence']} |")
    counts = {p: sum(d['priority'] == p for d in DOCS) for p in ("MVP", "P1", "P2", "OUT")}
    lines += ["", f"סה״כ {len(DOCS)} קטגוריות מסמך · MVP: {counts['MVP']} · P1: {counts['P1']} · P2: {counts['P2']} · מחוץ להיקף: {counts['OUT']}.", "",
              "## 2. כרטיסי מסמך — 23 התכונות לכל קטגוריה", ""]
    for i, d in enumerate(DOCS, 1):
        lines += [f"### 2.{i} {d['name_he']} — `{d['doc_type']}`", "", "| תכונה | ערך |", "|---|---|"]
        for k, h in COLUMNS:
            if k in ("doc_type",):
                continue
            v = d[k]
            if k == "requirement_class":
                v = f"{LABELS[v]} (`{v}`)"
            lines.append(f"| {h} | {str(v).replace('|', '/')} |")
        lines.append("")
